:root {
  --unified-toolbar-padding: 4px;
  --unified-drag-space: 30px;
  --unified-customization-padding: 30px;
  /* minimal possible toolbar height */
  --unified-toolbar-minimal-height: 30px;
  /* button border + button padding */
  --unified-toolbar-button-spacing-height: calc(2px + var(--button-padding) * 2);
  /* 1lh for the text */
  --unified-toolbar-content-min-height: calc(1lh + var(--unified-toolbar-button-spacing-height));
  /* searchbar field height + border + block padding */
  --unified-toolbar-searchbar-height: calc(1.45lh + 4px);

  &[uidensity="compact"] {
    --unified-toolbar-padding: 1px;
    --unified-drag-space: 15px;
    --unified-toolbar-minimal-height: 24px;
  }

  &[uidensity="touch"] {
    --unified-toolbar-padding: 7px;
  }

  &[sizemode="fullscreen"],
  &:not([customtitlebar]) {
    --unified-drag-space: 3px;
  }

  & .icons-above-text {
    /* icon plus gap is 19px, 1lh for the text */
    --unified-toolbar-content-min-height: calc(19px + 1lh + var(--unified-toolbar-button-spacing-height));
  }

  & .icons-only {
    /* icon size is 16px */
    --unified-toolbar-content-min-height: calc(16px + var(--unified-toolbar-button-spacing-height));
  }
}
